    public static function detectMime(string $path): string {
        if(!is_file($path))throw new Error('source_missing','Source unavailable.',500);$finfo=function_exists('finfo_open')?finfo_open(FILEINFO_MIME_TYPE):false;$mime=$finfo?finfo_file($finfo,$path):false;if($finfo)finfo_close($finfo);$mime=is_string($mime)?strtolower($mime):'application/octet-stream';$head=file_get_contents($path,false,null,0,32);if(!is_string($head))throw new Error('source_read_failed','Cannot read source.',500);$hex=strtolower(bin2hex($head));
        if(str_starts_with($head,'%PDF-'))return 'application/pdf';if(str_starts_with($hex,'ffd8ff'))return 'image/jpeg';if(str_starts_with($hex,'89504e470d0a1a0a'))return 'image/png';if(str_starts_with($head,'GIF8'))return 'image/gif';if(str_starts_with($head,'RIFF')&&substr($head,8,4)==='WEBP')return 'image/webp';if(str_starts_with($head,'RIFF')&&substr($head,8,4)==='WAVE')return 'audio/wav';if(str_starts_with($head,'OggS'))return 'audio/ogg';if(str_starts_with($head,"\x1A\x45\xDF\xA3"))return 'video/webm';if(strlen($head)>=12&&substr($head,4,4)==='ftyp')return 'video/mp4';if(str_starts_with($head,'ID3')||(isset($head[0],$head[1])&&ord($head[0])===0xff&&(ord($head[1])&0xe0)===0xe0))return 'audio/mpeg';if(str_starts_with($head,'PK'))return 'application/zip';return $mime;
