        if($mime==='video/mp4')$match=is_string($head)&&strlen($head)>=12&&substr($head,4,4)==='ftyp';elseif($mime==='image/webp')$match=is_string($head)&&str_starts_with($head,'RIFF')&&substr($head,8,4)==='WEBP';elseif($mime==='audio/wav')$match=is_string($head)&&str_starts_with($head,'RIFF')&&substr($head,8,4)==='WAVE';else foreach(self::SIGNATURES[$mime]??[] as $sig)if(str_starts_with($hex,$sig)){$match=true;break;}
