    private static function assertFilename(string $filename,string $mime,array $allowed): void {
        $safe=Utils::filename($filename);$lower=strtolower($safe);if($safe===''||$safe==='file')throw new Error('filename_invalid','A valid filename is required.',400);if(preg_match('/\.(php\d*|phtml|phar|cgi|pl|py|js|html?|svg|exe|dll|com|bat|cmd|sh)(\.|$)/i',$lower))throw new Error('executable_filename_denied','Executable or active-content filename denied.',415);$parts=explode('.',$lower);if(count($parts)>2){$danger=array_slice($parts,0,-1);foreach($danger as $part)if(in_array($part,['php','phtml','phar','exe','js','html','svg'],true))throw new Error('double_extension_denied','Dangerous double extension denied.',415);}if($allowed!==[]){$ext=strtolower(pathinfo($safe,PATHINFO_EXTENSION));if(!in_array($ext,$allowed,true))throw new Error('extension_denied','Extension denied.',415);}
