    private static function structuralProbe(string $path,string $mime,array $policy): array {
        $size=filesize($path);if($size===false)throw new Error('source_read_failed','Cannot determine source size.',500);$probe=['mime'=>$mime,'byte_size'=>(int)$size];
        if(str_starts_with($mime,'image/')){$info=@getimagesize($path);if(!is_array($info)||($info[0]??0)<1||($info[1]??0)<1)throw new Error('image_structure_invalid','Image structure invalid.',422);$pixels=(int)$info[0]*(int)$info[1];$limit=(int)($policy['max_pixels']??0);if($limit>0&&$pixels>$limit)throw new Error('pixel_bomb_detected','Image exceeds pixel budget.',413);if((int)($policy['max_width']??0)>0&&(int)$info[0]>(int)$policy['max_width'])throw new Error('image_width_exceeded','Image width exceeds policy.',413);if((int)($policy['max_height']??0)>0&&(int)$info[1]>(int)$policy['max_height'])throw new Error('image_height_exceeded','Image height exceeds policy.',413);$probe+=['width'=>(int)$info[0],'height'=>(int)$info[1],'pixels'=>$pixels];}
        elseif($mime==='application/pdf'){$head=file_get_contents($path,false,null,0,min(1048576,(int)$size));$tailLength=min(1048576,(int)$size);$tail=file_get_contents($path,false,null,max(0,(int)$size-$tailLength),$tailLength);if(!is_string($head)||!is_string($tail)||!str_starts_with($head,'%PDF-')||!str_contains($tail,'%%EOF'))throw new Error('pdf_structure_invalid','PDF is malformed/truncated.',422);$scan=self::scanPdf($path);$pages=max(1,(int)$scan['pages']);if((int)($policy['max_pages']??0)>0&&$pages>(int)$policy['max_pages'])throw new Error('pdf_page_limit_exceeded','PDF exceeds page limit.',413);if($scan['encrypted']&&!Utils::bool($policy['allow_encrypted_document']??false))throw new Error('encrypted_document_denied','Encrypted document denied by policy.',415);if($scan['active_content'])$probe['active_content_detected']=true;$probe['pages']=$pages;}
