    }
    private static function scanPdf(string $path): array {
        $h=fopen($path,'rb');if($h===false)throw new Error('source_read_failed','Cannot read PDF source.',500);$pages=0;$encrypted=false;$active=false;$overlap='';
        try{while(!feof($h)){$chunk=fread($h,1048576);if($chunk===false)throw new Error('source_read_failed','Cannot scan PDF source.',500);if($chunk==='')continue;$data=$overlap.$chunk;$pages+=preg_match_all('/\/Type\s*\/Page\b/',$data);$encrypted=$encrypted||preg_match('/\/Encrypt\b/',$data)===1;$active=$active||preg_match('/\/JavaScript\b|\/JS\b|\/Launch\b|\/EmbeddedFile\b/i',$data)===1;$overlap=substr($data,-256);}}finally{fclose($h);}return ['pages'=>$pages,'encrypted'=>$encrypted,'active_content'=>$active];
    }
    public static function range(?string $header,int $size,int $maxBytes): array {
        if($size<1||$maxBytes<1)throw new Error('range_policy_invalid','Range policy invalid.',500);if($header===null||$header==='')return ['start'=>0,'end'=>$size-1,'length'=>$size,'partial'=>false];if(!preg_match('/^bytes=(\d*)-(\d*)$/',$header,$m))throw new Error('range_invalid','Invalid Range header.',416);$start=$m[1]===''?null:(int)$m[1];$end=$m[2]===''?null:(int)$m[2];if($start===null){$length=min($size,max(1,$end??0));$start=$size-$length;$end=$size-1;}else{$end=$end??($size-1);}if($start<0||$end<$start||$end>=$size||$end-$start+1>$maxBytes)throw new Error('range_not_satisfiable','Requested range is outside policy.',416);return ['start'=>$start,'end'=>$end,'length'=>$end-$start+1,'partial'=>true];
    }
}

final class ArchiveInspector {
    public static function inspect(string $path,int $maxEntries,int $maxDepth,int $maxRatio): array {
        if(!class_exists('ZipArchive'))throw new Error('archive_scanner_unavailable','Zip inspection provider unavailable.',503);if($maxEntries<1||$maxDepth<1||$maxRatio<1)throw new Error('archive_policy_invalid','Archive policy invalid.',500);$zip=new \ZipArchive();if($zip->open($path)!==true)throw new Error('archive_invalid','Archive cannot be opened.',422);$entries=$zip->numFiles;
        try{if($entries>$maxEntries)throw new Error('archive_entry_limit','Archive entry limit exceeded.',413);$compressed=0;$uncompressed=0;$depth=0;$nested=0;for($i=0;$i<$entries;$i++){$stat=$zip->statIndex($i);if(!is_array($stat))throw new Error('archive_entry_invalid','Archive entry metadata invalid.',422);$rawName=(string)($stat['name']??'');$name=str_replace('\\','/',$rawName);$segments=explode('/',trim($name,'/'));if($name===''||str_contains($name,"\0")||str_starts_with($name,'/')||preg_match('/^[A-Za-z]:\//',$name)||in_array('..',$segments,true)||preg_match('/\.(php\d*|phtml|phar|cgi|pl|py|js|html?|svg|exe|dll|com|bat|cmd|sh)$/i',$name))throw new Error('archive_entry_denied','Archive contains unsafe entry.',415,['entry'=>Utils::filename($name)]);$opsys=0;$attributes=0;if(method_exists($zip,'getExternalAttributesIndex')&&$zip->getExternalAttributesIndex($i,$opsys,$attributes)&&$opsys===3&&(($attributes>>16)&0170000)===0120000)throw new Error('archive_symlink_denied','Archive symlink entry denied.',415,['entry'=>Utils::filename($name)]);$depth=max($depth,count($segments));$compressed+=(int)($stat['comp_size']??0);$uncompressed+=(int)($stat['size']??0);if(preg_match('/\.(zip|7z|rar|tar|gz|bz2|xz)$/i',$name))$nested++;}}
        finally{$zip->close();}
        if($depth>$maxDepth)throw new Error('archive_depth_limit','Archive path depth exceeds policy.',413);if($nested>0)throw new Error('nested_archive_requires_scanner','Nested archives require an approved recursive scanner.',422,['nested_entries'=>$nested]);$ratio=$compressed>0?$uncompressed/$compressed:($uncompressed>0?INF:1);if($ratio>$maxRatio)throw new Error('decompression_bomb_detected','Archive expansion ratio exceeds policy.',413);return ['archive_entries'=>$entries,'archive_depth'=>$depth,'nested_archives'=>$nested,'compressed_bytes'=>$compressed,'uncompressed_bytes'=>$uncompressed,'expansion_ratio'=>$ratio];
    }
}

final class ToolRunner {
    public static function probe(string $path,string $mime,array $policy): array {return self::call('probe',['path'=>$path,'mime'=>$mime,'limits'=>['duration'=>(int)($policy['max_duration_seconds']??0),'size'=>(int)$policy['max_size_bytes']]]);}
    public static function transform(string $operation,mixed $source,array $specification): array {return self::call('transform',['operation'=>Utils::key($operation,64),'source'=>$source,'specification'=>$specification]);}
    public static function call(string $operation,array $request): array {
        $provider=function_exists('apply_filters')?apply_filters('scm_sandbox_tool_result',null,$operation,Utils::redact($request)):null;if(!is_array($provider))throw new Error('sandbox_provider_unavailable','Approved sandbox worker unavailable.',503,['operation'=>$operation]);foreach(['passed','worker_id','worker_version','non_root','network_isolated','ephemeral','resource_limits','output'] as $field)if(!array_key_exists($field,$provider))throw new Error('sandbox_attestation_incomplete','Sandbox attestation incomplete.',503,['field'=>$field]);
        if($provider['passed']!==true||$provider['non_root']!==true||$provider['network_isolated']!==true||$provider['ephemeral']!==true||!is_array($provider['resource_limits'])||!is_array($provider['output']))throw new Error('sandbox_execution_failed','Sandbox worker did not satisfy isolation policy.',422,['operation'=>$operation]);$workerId=Utils::text((string)$provider['worker_id'],96);$workerVersion=Utils::text((string)$provider['worker_version'],64);if($workerId===''||$workerVersion===''||$workerVersion==='unknown')throw new Error('sandbox_attestation_incomplete','Sandbox worker identity/version invalid.',503);foreach(['cpu_seconds','memory_bytes'] as $limit)if((int)($provider['resource_limits'][$limit]??0)<1)throw new Error('sandbox_attestation_incomplete','Sandbox resource limit invalid.',503,['field'=>$limit]);return $provider['output']+['worker'=>['id'=>$workerId,'version'=>$workerVersion,'non_root'=>true,'network_isolated'=>true,'ephemeral'=>true,'resource_limits'=>$provider['resource_limits']]];
    }
}

final class ScannerRegistry {
    private static array $scanners=[];
    public static function reset(): void {self::$scanners=[];}
    public static function register(string $id,callable $scanner,array $meta): void {
        $id=Utils::key($id,64);Utils::requireFields($meta,['version','timeout_seconds','max_depth','capabilities'],'scanner_metadata_incomplete');$version=Utils::text((string)$meta['version'],64);$capabilities=array_values(array_filter(array_unique(array_map(fn($value)=>Utils::key((string)$value,64),(array)$meta['capabilities']))));if($id===''||$version===''||(int)$meta['timeout_seconds']<1||(int)$meta['max_depth']<1||$capabilities===[])throw new Error('scanner_metadata_incomplete','Scanner metadata invalid.',500);if(isset(self::$scanners[$id]))throw new Error('scanner_duplicate','Scanner already registered.',500,['scanner'=>$id]);$meta['version']=$version;$meta['capabilities']=$capabilities;self::$scanners[$id]=['callback'=>$scanner,'meta'=>$meta];
    }
    public static function registerWordPressAdapters(): void {if(!function_exists('apply_filters'))return;foreach(['malware','archive','polyglot','decompression_bomb','metadata','technical_safety'] as $id){self::register($id,function($stream,$context)use($id){return apply_filters('scm_'.$id.'_scan_result',null,$stream,$context);},['version'=>(string)apply_filters('scm_'.$id.'_scanner_version','unknown'),'timeout_seconds'=>(int)apply_filters('scm_'.$id.'_scanner_timeout',30),'max_depth'=>(int)apply_filters('scm_'.$id.'_scanner_depth',5),'capabilities'=>[$id]]);}}
    public static function scan($stream,array $required,array $context): array {
        if(!is_resource($stream))throw new Error('stream_invalid','Invalid scanner stream.',500);$results=[];$required=array_values(array_unique(array_filter(array_map(fn($value)=>Utils::key((string)$value,64),$required))));
        foreach($required as $id){if(in_array($id,['hash','magic','mime'],true))continue;if(!isset(self::$scanners[$id]))throw new Error('scanner_unavailable','Required scanner unavailable.',503,['scanner'=>$id]);$meta=self::$scanners[$id]['meta'];if(($meta['version']??'')==='unknown')throw new Error('scanner_version_unknown','Required scanner version is unknown.',503,['scanner'=>$id]);rewind($stream);$trustedContext=array_replace(Utils::redact($context),$meta,['scanner_id'=>$id,'scanner_version'=>$meta['version']]);try{$result=(self::$scanners[$id]['callback'])($stream,$trustedContext);}catch(\Throwable $exception){throw new Error('scanner_failed','Scanner failed closed.',503,['scanner'=>$id,'exception'=>get_class($exception)]);}if(!is_array($result)||($result['passed']??false)!==true)throw new Error('media_scan_failed','Required scan did not pass.',422,['scanner'=>$id,'reason'=>is_array($result)?($result['reason']??'failed'):'invalid_result']);$results[$id]=Utils::redact($result)+['version'=>$meta['version'],'scanner_id'=>$id];}
        rewind($stream);return $results;
    }
}

final class MetadataPolicy {
    public static function transform(string $mediaClass,array $source,array $policy): array {
        $result=ToolRunner::transform('metadata-policy',$source,['media_class'=>$mediaClass,'policy'=>$policy['metadata'],'rights'=>$policy['rights']]);foreach(['output_stream','metadata_removed','metadata_preserved'] as $field)if(!array_key_exists($field,$result))throw new Error('metadata_transform_incomplete','Metadata transform result incomplete.',503,['field'=>$field]);if(!is_resource($result['output_stream']))throw new Error('metadata_transform_invalid','Metadata transform output stream invalid.',503);$removed=array_map('strtolower',(array)$result['metadata_removed']);foreach(['gps','location'] as $sensitive)if(($policy['metadata']['strip_location']??true)&&!in_array($sensitive,$removed,true))throw new Error('metadata_privacy_failed','Location metadata was not proven stripped.',422,['field'=>$sensitive]);if(($policy['metadata']['strip_device']??true)&&!in_array('device',$removed,true))throw new Error('metadata_privacy_failed','Device metadata was not proven stripped.',422,['field'=>'device']);if(($policy['metadata']['strip_author']??true)&&!in_array('author',$removed,true))throw new Error('metadata_privacy_failed','Author metadata was not proven stripped.',422,['field'=>'author']);return $result;
    }
}

final class SafetySignalService {
    public static function evaluate($stream,array $asset): array {if(!is_resource($stream))throw new Error('stream_invalid','Invalid safety stream.',500);$scanner=self::scanOptional($stream,$asset);$confidence=(float)($scanner['confidence']??0.0);if($confidence<0||$confidence>1)throw new Error('safety_signal_invalid','Safety confidence invalid.',503);$record=['actor_id'=>0,'asset_id'=>$asset['asset_id'],'model_id'=>Utils::text((string)($scanner['model_id']??'technical-signal'),96),'model_version'=>Utils::text((string)($scanner['model_version']??'unknown'),64),'confidence'=>$confidence,'signals'=>(array)($scanner['signals']??[]),'status'=>'pending_review','autonomous_decision'=>false,'created_at'=>Utils::now()];if($confidence>=(float)$asset['policy']['safety']['minimum_confidence']&&!Utils::bool($scanner['requires_review']??false))$record['status']='informational';return RecordStore::put('safety_signal',Utils::id('sig'),$record);}
    private static function scanOptional($stream,array $asset): array {if(!function_exists('apply_filters'))return ['confidence'=>0.0,'signals'=>[],'requires_review'=>true,'model_id'=>'none','model_version'=>'none'];rewind($stream);$result=apply_filters('scm_technical_safety_signal',null,$stream,Utils::redact($asset));rewind($stream);return is_array($result)?$result:['confidence'=>0.0,'signals'=>[],'requires_review'=>true,'model_id'=>'none','model_version'=>'none'];}
    public static function review(string $signalId,int $reviewer,string $decision,string $reason): array {Auth::capability('media_review_safety_signals');Auth::assertActor($reviewer,'manage_options');$record=RecordStore::get('safety_signal',$signalId);if(!$record)throw new Error('safety_signal_not_found','Safety signal not found.',404);if(($record['status']??'')!=='pending_review')throw new Error('safety_signal_state_invalid','Safety signal is not awaiting review.',409);if(!in_array($decision,['accepted','rejected','escalated'],true))throw new Error('safety_decision_invalid','Invalid review decision.',400);$reason=Utils::text($reason,500);if($reason==='')throw new Error('safety_review_reason_required','Safety review reason is required.',400);$record['status']=$decision;$record['reviewer_id']=$reviewer;$record['review_reason']=$reason;$record['reviewed_at']=Utils::now();return RecordStore::put('safety_signal',$signalId,$record,(int)$record['version']);}
}
